// ─────────────────────────────────────────────────────────────────────────────
// Code node: "Init Run"
//
// Generates run metadata used throughout the workflow.
//
// Upstream: a Set node that injects { trigger, mode }
//   - trigger: "backfill" | "webhook" | "cron"
//   - mode:    "backfill" | "sync"
//
// Downstream consumers reference $('Init Run').first().json
// ─────────────────────────────────────────────────────────────────────────────

function uuidv4() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

const trigger = $json.trigger || 'backfill';
const mode = $json.mode || (trigger === 'backfill' ? 'backfill' : 'sync');

return [
  {
    json: {
      run_id: uuidv4(),
      started_at: new Date().toISOString(),
      trigger,
      mode,
    },
  },
];

// ─────────────────────────────────────────────────────────────────────────────
// Code node: "Split Patients"
//
// Joins Supabase Clientes <-> Gestek clientes by NORMALIZED NAME.
//
// WHY name and not id: Supabase \"Clientes\".id is a legacy sequential text id
// (\"330\", \"329\"...), while Gestek ids are Mongo ObjectIds
// (\"691486a8437ac8cf1e29f38d\"). They never overlap, so id-matching produced
// zero matches. Normalized name matches ~100% of fetched clients.
//
// Upstream:
//   $('Build Clientes Map').first().json  → { idMap, nameToId, duplicates }
//   $('Read Supabase Patients').all()     → Clientes rows { id, Nome, ... }
//
// Output (single item):
//   {
//     gestekIdToSupabaseId: { [gestekObjectId]: supabaseId },  // resolved matches
//     supabaseNameToId:     { [normName]: supabaseId },        // fallback lookups
//     existingGestekIds:    [gestekId, ...],
//     newGestekClients:     [{ id, nome, dataCriacao }],       // sync mode INSERTs these
//     orphanSupabasePatients: [{ id, Nome }],                  // in Supabase, not in Gestek
//     duplicates: [...]                                         // name-collision warnings
//   }
// ─────────────────────────────────────────────────────────────────────────────

const normalize = (s) =>
  (s || '')
    .trim()
    .replace(/\s+/g, ' ')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase();

const { idMap, nameToId, duplicates } = $('Build Clientes Map').first().json;
const supabasePatients = $('Read Supabase Patients').all().map((i) => i.json);

// Build normalized-name -> Supabase id (first row wins; warn on collisions).
const supabaseNameToId = {};
const supabaseDuplicates = [];
for (const p of supabasePatients) {
  if (!p.id) continue;
  const key = normalize(p.Nome);
  if (!key) continue;
  if (supabaseNameToId[key] && supabaseNameToId[key] !== p.id) {
    supabaseDuplicates.push({
      level: 'warn',
      message: `Duplicate Supabase name \"${key}\" — kept id ${supabaseNameToId[key]}, ignored ${p.id}`,
    });
  } else {
    supabaseNameToId[key] = p.id;
  }
}

// Resolve each Gestek client to a Supabase id by name.
const gestekIdToSupabaseId = {};
const existingGestekIds = [];
const newGestekClients = [];
for (const [gestekId, info] of Object.entries(idMap)) {
  const key = normalize(info.nome);
  const supaId = key ? supabaseNameToId[key] : undefined;
  if (supaId) {
    gestekIdToSupabaseId[gestekId] = supaId;
    existingGestekIds.push(gestekId);
  } else {
    newGestekClients.push({
      id: gestekId,
      nome: info.nome,
      dataCriacao: info.dataCriacao,
    });
  }
}

// Supabase rows whose name has no Gestek counterpart.
const orphanSupabasePatients = [];
for (const p of supabasePatients) {
  const key = normalize(p.Nome);
  if (key && !nameToId[key]) {
    orphanSupabasePatients.push({ id: p.id, Nome: p.Nome });
  }
}

return [
  {
    json: {
      gestekIdToSupabaseId,
      supabaseNameToId,
      existingGestekIds,
      newGestekClients,
      orphanSupabasePatients,
      duplicates: [...(duplicates || []), ...supabaseDuplicates],
    },
  },
];

// ─────────────────────────────────────────────────────────────────────────────
// Code node: "Build Clientes Map"
//
// Consumes ALL items from the paginated /api/clientes loop and produces a
// single item containing:
//   - idMap:     { [gestek_client_id]: { nome, dataCriacao } }
//   - nameToId:  { [normalized_name]: gestek_client_id }
//   - duplicates: [{ level, message }] — name collisions
//   - totalClientes
//
// Each input item's $json is the raw HTTP response body:
//   - either: { clientes: [...], totais: {...} }
//   - or:    [{ clientes: [...], totais: {...} }] (wrapped)
// ─────────────────────────────────────────────────────────────────────────────

const normalize = (s) =>
  (s || '')
    .trim()
    .replace(/\s+/g, ' ')
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase();

const idMap = {};
const nameToId = {};
const duplicates = [];

for (const item of $input.all()) {
  let payload = item.json;
  if (Array.isArray(payload)) payload = payload[0];

  const clientes = (payload && payload.clientes) || [];
  for (const c of clientes) {
    if (!c.id) continue;

    idMap[c.id] = {
      nome: c.nome,
      dataCriacao: c.dataCriacao,
    };

    const key = normalize(c.nome);
    if (!key) continue;

    if (nameToId[key] && nameToId[key] !== c.id) {
      duplicates.push({
        level: 'warn',
        message: `Duplicate normalized name "${key}" — kept ${nameToId[key]}, ignored ${c.id} (${c.nome})`,
      });
    } else {
      nameToId[key] = c.id;
    }
  }
}

return [
  {
    json: {
      idMap,
      nameToId,
      duplicates,
      totalClientes: Object.keys(idMap).length,
    },
  },
];

