// ─────────────────────────────────────────────────────────────────────────────
// Code node: "Generate Monthly Windows"
//
// Produces one output item per calendar month from min("Data do Cadastro") → today.
// Each item is consumed by a downstream "Split In Batches" → HTTP /api/vendas
// loop.
//
// "Data do Cadastro" is stored as text in Brazilian format "DD/MM/YY HH:MM",
// implicit São Paulo time (UTC-3, no DST since 2019).
//
// Window boundaries are INCLUSIVE on both ends:
//   start = YYYY-MM-01T00:00:00.000Z
//   end   = YYYY-MM-LASTDAYT23:59:59.999Z  (clamped to today if in current month)
//
// Upstream: $('Read Supabase Patients').all()
// Output: array of items, each { json: { start, end, label } }
// ─────────────────────────────────────────────────────────────────────────────

function parseBRDate(s) {
  const m = (s || '').match(/^(\d{2})\/(\d{2})\/(\d{2})\s+(\d{2}):(\d{2})$/);
  if (!m) return null;
  const [, dd, mm, yy, hh, mi] = m;
  return new Date(
    Date.UTC(
      2000 + parseInt(yy, 10),
      parseInt(mm, 10) - 1,
      parseInt(dd, 10),
      parseInt(hh, 10) + 3, // BRT → UTC
      parseInt(mi, 10)
    )
  );
}

const patients = $('Read Supabase Patients').all().map((i) => i.json);

const dateNums = patients
  .map((p) => parseBRDate(p['Data do Cadastro']))
  .filter((d) => d instanceof Date && !Number.isNaN(d.getTime()))
  .map((d) => d.getTime());

if (dateNums.length === 0) {
  throw new Error(
    'No patients with parseable "Data do Cadastro" found in Clientes — cannot determine backfill start.'
  );
}

const minDate = new Date(Math.min(...dateNums));
const today = new Date();

const cursor = new Date(
  Date.UTC(minDate.getUTCFullYear(), minDate.getUTCMonth(), 1, 0, 0, 0, 0)
);
const stopAt = new Date(
  Date.UTC(
    today.getUTCFullYear(),
    today.getUTCMonth(),
    today.getUTCDate(),
    23,
    59,
    59,
    999
  )
);

const out = [];
while (cursor.getTime() <= stopAt.getTime()) {
  const start = new Date(cursor);
  const lastDayOfMonth = new Date(
    Date.UTC(start.getUTCFullYear(), start.getUTCMonth() + 1, 0, 23, 59, 59, 999)
  );
  const end = lastDayOfMonth.getTime() > stopAt.getTime() ? stopAt : lastDayOfMonth;

  out.push({
    json: {
      start: start.toISOString(),
      end: end.toISOString(),
      label: `${start.getUTCFullYear()}-${String(start.getUTCMonth() + 1).padStart(2, '0')}`,
    },
  });

  cursor.setUTCMonth(cursor.getUTCMonth() + 1);
}

return out;

const accumulator = {};
let totalSalesAggregated = 0;

for (const item of $input.all()) {
  let payload = item.json;
  if (Array.isArray(payload)) payload = payload[0];

  const vendas = (payload && payload.vendas) || [];
  for (const venda of vendas) {
    if (venda.status !== 1) continue;
    if (!venda.clienteId) continue;

    const id = venda.clienteId;
    if (!accumulator[id]) {
      accumulator[id] = {
        nome: venda.cliente || null,
        vendas: 0,
        receita: 0,
        descontos: 0,
        procedimentos: {},
      };
    }
    const acc = accumulator[id];
    acc.vendas += 1;
    acc.receita += Number(venda.total) || 0;
    acc.descontos += Number(venda.desconto) || 0;

    for (const it of venda.itens || []) {
      const name = it.nome;
      const qty = Number(it.quantidade) || 0;
      if (!name) continue;
      acc.procedimentos[name] = (acc.procedimentos[name] || 0) + qty;
    }

    totalSalesAggregated += 1;
  }
}

return [
  {
    json: {
      accumulator,
      totalSalesAggregated,
    },
  },
];

// Maps aggregated sales (keyed by Gestek clienteId / ObjectId) onto the
// Supabase row id, using the name-resolved map from Split Patients.
//
// Resolution order for each Gestek clienteId:
//   1. gestekIdToSupabaseId  (existing Supabase row matched by name)
//   2. if it is a brand-new client inserted THIS run (sync mode), its Supabase
//      row id IS the Gestek ObjectId (Insert New Patients writes id = gestekId)
//   3. fallback: normalize the sale's own client name -> supabaseNameToId
//   4. otherwise -> unmatched (reported as a warning)

const normalize = (s) =>
  (s || '')
    .trim()
    .replace(/\s+/g, ' ')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase();

const { accumulator } = $('Aggregate Sales').first().json;
const split = $('Split Patients').first().json;
const { gestekIdToSupabaseId, supabaseNameToId, newGestekClients } = split;

const newIdSet = new Set((newGestekClients || []).map((c) => c.id));

const money = (n) => (Math.round(n * 100) / 100).toFixed(2);
const count = (n) => String(n);

const rpcPayload = [];
const unmatchedSales = [];

for (const [gestekId, agg] of Object.entries(accumulator)) {
  let supaId = gestekIdToSupabaseId[gestekId];
  if (!supaId && newIdSet.has(gestekId)) supaId = gestekId;
  if (!supaId) {
    const key = normalize(agg.nome);
    if (key && supabaseNameToId[key]) supaId = supabaseNameToId[key];
  }
  if (!supaId) {
    unmatchedSales.push({ clienteId: gestekId, nome: agg.nome, sale_count: agg.vendas });
    continue;
  }

  const procedimentos = Object.entries(agg.procedimentos)
    .sort((a, b) => b[1] - a[1])
    .map(([nome, qty]) => `${nome} (${qty})`)
    .join(', ');

  rpcPayload.push({
    id: supaId,
    procedimentos: procedimentos || null,
    numero_de_vendas: count(agg.vendas),
    receita_total: money(agg.receita),
    descontos: money(agg.descontos),
    ticket_medio: agg.vendas > 0 ? money(agg.receita / agg.vendas) : null,
  });
}

return [
  {
    json: {
      rpcPayload,
      unmatchedSales,
      rowCount: rpcPayload.length,
    },
  },
];

const init = $('Init Run').first().json;
const split = $('Split Patients').first().json;
const aggregate = $('Aggregate Sales').first().json;
const payload = $('Build Update Payload').first().json;
const windowCount = $('Generate Monthly Windows').all().length;

const completed_at = new Date().toISOString();

const summary = {
  run_id: init.run_id,
  started_at: init.started_at,
  completed_at,
  trigger: init.trigger,
  mode: init.mode,
  patients_updated: payload.rowCount,
  new_patients_inserted: init.mode === 'sync' ? split.newGestekClients.length : 0,
  unmatched_sales: payload.unmatchedSales.length,
  duplicate_name_warnings: (split.duplicates || []).length,
  orphan_supabase_patients: split.orphanSupabasePatients.length,
  monthly_windows_processed: windowCount,
  total_sales_aggregated: aggregate.totalSalesAggregated,
};

const warnings = [
  ...(split.duplicates || []),
  ...split.orphanSupabasePatients.map((p) => ({
    level: 'warn',
    message: `Supabase patient "${p.Nome}" (id=${p.id}) has no matching Gestek client — Gestek may have deleted them`,
  })),
  ...payload.unmatchedSales.map((s) => ({
    level: 'warn',
    message: `Sales for unknown clienteId ${s.clienteId} (${s.sale_count} sales)`,
  })),
];

return [{ json: { summary, warnings, completed_at } }];

